values ('f442b2ea-a4ce-5f40-b594-83f5c99dc2f0', null, '{"nl":"Squat met halter","en":"Barbell back squat","de":"Kniebeuge mit Langhantel"}'::jsonb, '{"nl":"Halter op je bovenrug, voeten op schouderbreedte. Zak met een rechte rug tot je heupen minstens op kniehoogte zijn en duw jezelf weer omhoog.","en":"Bar on your upper back, feet shoulder-width apart. Sit down with a straight back until your hips are at least at knee height, then drive back up.","de":"Hantel auf dem oberen Rücken, Füße schulterbreit. Geh mit geradem Rücken in die Knie, bis die Hüfte mindestens auf Kniehöhe ist, und drück dich wieder hoch."}'::jsonb, 'compound', 'external', 'barbell', array['quads', 'glutes']::text[], array['hamstrings', 'core']::text[], 2.5, '2026-11-19T00:00:00Z'::timestamptz + interval '0 seconds')
