values ('a3f70683-d7a6-5577-b898-b7f95390975f', null, '{"nl":"Deadlift","en":"Deadlift","de":"Kreuzheben"}'::jsonb, '{"nl":"Halter boven je middenvoet, handen net buiten je knieën. Span je rug aan en til de halter langs je benen op tot je rechtop staat.","en":"Bar over your mid-foot, hands just outside your knees. Brace your back and lift the bar along your legs until you stand tall.","de":"Hantel über dem Mittelfuß, Hände knapp außerhalb der Knie. Spann den Rücken an und heb die Hantel an den Beinen entlang, bis du aufrecht stehst."}'::jsonb, 'compound', 'external', 'barbell', array['hamstrings', 'glutes', 'back']::text[], array['quads', 'forearms', 'core']::text[], 2.5, '2026-11-19T00:00:00Z'::timestamptz + interval '0 seconds')
