values ('8d3017b9-0763-5488-ba4f-ac8cc5a87de8', null, '{"nl":"Schouderdrukken met halter","en":"Overhead press","de":"Schulterdrücken mit Langhantel"}'::jsonb, '{"nl":"Halter op je sleutelbeen, billen en buik aangespannen. Druk de halter recht boven je hoofd en laat hem gecontroleerd terugkomen.","en":"Bar on your collarbones, glutes and core tight. Press the bar straight overhead and bring it back down under control.","de":"Hantel auf dem Schlüsselbein, Po und Bauch angespannt. Drück die Hantel gerade über den Kopf und senke sie kontrolliert."}'::jsonb, 'compound', 'external', 'barbell', array['shoulders']::text[], array['triceps', 'core']::text[], 2.5, '2026-11-19T00:00:00Z'::timestamptz + interval '0 seconds')
