values ('0ae4d3fb-925b-5f0c-98c1-e453729b0e17', null, '{"nl":"Triceps pushdown","en":"Triceps pushdown","de":"Trizepsdrücken am Kabel"}'::jsonb, '{"nl":"Ellebogen tegen je zij. Duw de greep naar beneden tot je armen gestrekt zijn en laat hem rustig terugkomen.","en":"Elbows at your sides. Push the handle down until your arms are straight and let it come back slowly.","de":"Ellbogen am Körper. Drück den Griff nach unten, bis die Arme gestreckt sind, und lass ihn ruhig zurück."}'::jsonb, 'isolation', 'external', 'cable', array['triceps']::text[], array[]::text[], 5, '2026-11-19T00:00:00Z'::timestamptz + interval '0 seconds')
