insert into public.exercises (id, owner_id, name, instructions, kind, load_type, equipment, primary_muscles, secondary_muscles, default_step_kg, updated_at)
values ('35a39c5f-d6d0-55a0-8107-6a62eecab0c8', null, '{"nl":"Face pull","en":"Face pull","de":"Face Pull"}'::jsonb, '{"nl":"Kabel op gezichtshoogte, touw in beide handen. Trek het touw naar je gezicht met je ellebogen hoog en laat het langzaam terug.","en":"Cable at face height, rope in both hands. Pull the rope towards your face with your elbows high and let it return slowly.","de":"Kabel auf Gesichtshöhe, Seil in beiden Händen. Zieh das Seil mit hohen Ellbogen zum Gesicht und lass es langsam zurück."}'::jsonb, 'isolation', 'external', 'cable', array['shoulders']::text[], array['back']::text[], 5, '2026-11-19T00:00:00Z'::timestamptz + interval '0 seconds')
