insert into public.exercises (id, owner_id, name, instructions, kind, load_type, equipment, primary_muscles, secondary_muscles, default_step_kg, updated_at)
values ('ee78b930-91da-58d7-8295-aa740206a7a6', null, '{"nl":"Kabel crossover","en":"Cable fly","de":"Kabelzug-Flys"}'::jsonb, '{"nl":"Sta tussen de kabels met licht gebogen armen. Breng je handen voor je borst samen en laat ze gecontroleerd terug.","en":"Stand between the cables with slightly bent arms. Bring your hands together in front of your chest and let them return under control.","de":"Steh zwischen den Kabeln mit leicht gebeugten Armen. Führ die Hände vor der Brust zusammen und lass sie kontrolliert zurück."}'::jsonb, 'isolation', 'external', 'cable', array['chest']::text[], array['shoulders']::text[], 5, '2026-11-19T00:00:00Z'::timestamptz + interval '0 seconds')
