values ('1eba5fd1-f1c8-5159-9897-460d3f7a108c', null, '{"nl":"Crunch aan de kabel","en":"Cable crunch","de":"Kabel-Crunch"}'::jsonb, '{"nl":"Kniel voor de kabel met het touw bij je hoofd. Rol je romp naar beneden met je buikspieren en kom langzaam terug.","en":"Kneel in front of the cable with the rope by your head. Curl your torso down with your abs and come back slowly.","de":"Knie vor dem Kabel, das Seil am Kopf. Roll den Oberkörper mit den Bauchmuskeln nach unten und komm langsam zurück."}'::jsonb, 'isolation', 'external', 'cable', array['core']::text[], array[]::text[], 5, '2026-11-19T00:00:00Z'::timestamptz + interval '0 seconds')
