values ('0ef54d09-600e-593d-876f-9c24b9f3f708', null, '{"nl":"Optrekken","en":"Pull-up","de":"Klimmzug"}'::jsonb, '{"nl":"Hang aan de stang met gestrekte armen. Trek jezelf op tot je kin boven de stang is en zak gecontroleerd terug.","en":"Hang from the bar with straight arms. Pull yourself up until your chin is over the bar and lower under control.","de":"Häng mit gestreckten Armen an der Stange. Zieh dich hoch, bis das Kinn über der Stange ist, und senke dich kontrolliert."}'::jsonb, 'compound', 'bodyweight', 'bodyweight', array['back']::text[], array['biceps']::text[], 2.5, '2026-11-19T00:00:00Z'::timestamptz + interval '0 seconds')
