values ('b22e8cdd-fa8f-5a01-9449-859d3666fa78', null, '{"nl":"Opdrukken","en":"Push-up","de":"Liegestütz"}'::jsonb, '{"nl":"Handen iets breder dan je schouders, lichaam in een rechte lijn. Zak tot je borst bijna de grond raakt en druk jezelf op.","en":"Hands slightly wider than your shoulders, body in a straight line. Lower until your chest almost touches the floor and push up.","de":"Hände etwas breiter als die Schultern, Körper in einer Linie. Geh runter, bis die Brust fast den Boden berührt, und drück dich hoch."}'::jsonb, 'compound', 'bodyweight', 'bodyweight', array['chest']::text[], array['triceps', 'shoulders']::text[], 2.5, '2026-11-19T00:00:00Z'::timestamptz + interval '0 seconds')
