values ('d84cf82f-2ee4-52d4-9392-0d1833ca3aab', null, '{"nl":"Dippen","en":"Dip","de":"Dip"}'::jsonb, '{"nl":"Steun op de leggers met gestrekte armen. Zak tot je bovenarmen ongeveer horizontaal zijn en druk jezelf omhoog.","en":"Support yourself on the bars with straight arms. Lower until your upper arms are about level and push yourself up.","de":"Stütz dich mit gestreckten Armen auf den Holmen. Geh runter, bis die Oberarme etwa waagerecht sind, und drück dich hoch."}'::jsonb, 'compound', 'bodyweight', 'bodyweight', array['chest', 'triceps']::text[], array['shoulders']::text[], 2.5, '2026-11-19T00:00:00Z'::timestamptz + interval '0 seconds')
