values ('96db441e-09eb-5089-b615-0cefc1a34bb0', null, '{"nl":"Hangend benen heffen","en":"Hanging leg raise","de":"Hängendes Beinheben"}'::jsonb, '{"nl":"Hang aan de stang. Hef je benen tot heuphoogte zonder te zwaaien en laat ze langzaam zakken.","en":"Hang from the bar. Raise your legs to hip height without swinging and lower them slowly.","de":"Häng an der Stange. Heb die Beine ohne Schwung bis auf Hüfthöhe und senke sie langsam."}'::jsonb, 'isolation', 'bodyweight', 'bodyweight', array['core']::text[], array[]::text[], 2.5, '2026-11-19T00:00:00Z'::timestamptz + interval '0 seconds')
